		return "no offer"
	end
	if offer.status == "pending" then
		return "waiting for confirmation"
	end
	if offer.status == "declined" then
		return "declined"
	end
	if offer.status == "accepted" then
		return "accepted"
	end
	if offer.status == "ready" then
		return "connected"
	end
	return tostring(offer.status)
end

